-- Sports Booking System - Supabase PostgreSQL schema
-- How to run:
-- 1. Open Supabase Dashboard > SQL Editor > New query.
-- 2. Paste this whole file and click Run.
-- 3. Seed account password for all sample users is: 123456.
--    The database stores only bcrypt hashes generated by pgcrypto.
--
-- ===== QUY ƯỚC ID (varchar, prefix = viết tắt tên bảng) =====
-- users                  → u0001, u0002, ...
-- partner_profiles       → pp0001, pp0002, ...
-- court_categories       → cc0001, cc0002, ...
-- courts                 → c0001, c0002, ...
-- court_surfaces         → csf0001
-- court_images           → ci0001
-- court_amenities        → ca0001
-- court_prices           → cp0001
-- court_base_prices      → cbp0001
-- dynamic_pricing_rules  → dr0001
-- court_services         → cs0001
-- bookings               → b0001
-- demand_predictions     → dp0001
-- demand_features        → df0001
-- booking_services       → bs0001
-- reviews                → rv0001
-- reports                → rp0001
-- notifications          → nf0001
-- analytics_events       → ae0001
-- vouchers               → v0001
-- user_vouchers          → uv0001
-- booking_vouchers       → bv0001
-- blog_categories        → bc0001
-- blog_posts             → bp0001
-- blog_comments          → bco0001
-- blog_likes             → bl0001
-- tournaments            → tn0001
-- tournament_registrations → tr0001
-- team_recruitment_posts → tp0001
-- ================================================

create extension if not exists "pgcrypto";

