drop table if exists demand_predictions cascade;
drop table if exists dynamic_pricing_rules cascade;
drop table if exists court_base_prices cascade;
drop table if exists team_recruitment_posts cascade;
drop table if exists tournament_registrations cascade;
drop table if exists tournaments cascade;
drop table if exists blog_likes cascade;
drop table if exists blog_comments cascade;
drop table if exists blog_posts cascade;
drop table if exists blog_categories cascade;
drop table if exists booking_vouchers cascade;
drop table if exists payment_transactions cascade;
drop table if exists payments cascade;
drop table if exists booking_slots cascade;
drop table if exists user_vouchers cascade;
drop table if exists vouchers cascade;
drop table if exists reviews cascade;
drop table if exists booking_services cascade;
drop table if exists bookings cascade;
drop table if exists court_services cascade;
drop table if exists court_availability_blocks cascade;
drop table if exists court_prices cascade;
drop table if exists court_amenities cascade;
drop table if exists court_surfaces cascade;
drop table if exists court_images cascade;
drop table if exists courts cascade;
drop table if exists court_categories cascade;
drop table if exists partner_profiles cascade;
drop table if exists users cascade;

drop type if exists report_status cascade;
drop type if exists analytics_event_type cascade;
drop type if exists demand_prediction_status cascade;
drop type if exists demand_prediction_level cascade;
drop type if exists dynamic_pricing_rule_status cascade;
drop type if exists price_adjustment_type cascade;
drop type if exists dynamic_pricing_rule_type cascade;
drop type if exists team_recruitment_status cascade;
drop type if exists tournament_registration_status cascade;
drop type if exists tournament_status cascade;
drop type if exists blog_visibility cascade;
drop type if exists blog_post_status cascade;
drop type if exists user_voucher_status cascade;
drop type if exists voucher_status cascade;
drop type if exists voucher_discount_type cascade;
drop type if exists review_display_status cascade;
drop type if exists day_type cascade;
drop type if exists payment_method cascade;
drop type if exists payment_type cascade;
drop type if exists payment_status cascade;
drop type if exists booking_status cascade;
drop type if exists availability_block_status cascade;
drop type if exists court_active_status cascade;
drop type if exists approval_status cascade;
drop type if exists account_status cascade;
drop type if exists auth_provider cascade;
drop type if exists verification_purpose cascade;
drop type if exists user_role cascade;

